func (this *Display) internal_dispose_GC_(hDC int64, data *GCData) {
	gtk.CairoCairo_destroy(hDC)
}

func (this *Display) internal_new_GC_(data *GCData) int64 {
	if this.IsDisposed() {
		this.Error(ERROR_DEVICE_DISPOSED)
	}
	var gc int64 = int64(0)
	var root int64 = int64(0)
	if gtk.GTKGTK4 {
		var surface int64 = gtk.CairoCairo_image_surface_create(gtk.CairoCAIRO_FORMAT_A8, data.Width, data.Height)
		gc = gtk.CairoCairo_create(surface)
	} else {
		root = gtk.GDKGdk_get_default_root_window()
		gc = gtk.GDKGdk_cairo_create(root)
	}
	if gc == 0 {
		this.Error(ERROR_NO_HANDLES)
	}
	if data != (nil) {
		var mask int32 = LEFT_TO_RIGHT | RIGHT_TO_LEFT
		if (data.Style & mask) == 0 {
			data.Style |= LEFT_TO_RIGHT
		}
		data.Device = upcastDisplayToDevice(this)
		data.Drawable = root
		data.BackgroundRGBA = this.impl.getSystemColor_(COLOR_WHITE).Handle
		data.ForegroundRGBA = this.impl.getSystemColor_(COLOR_BLACK).Handle
		data.Font = this.GetSystemFont()
	}
	return gc
}

func DisplayInversePremultipliedColor(color int32, alpha int32) int32 {
	if alpha == 0 {
		return 0
	}
	return (255*color + alpha - 1) / alpha
}

