func (this *Display) Map(fromLike ControlLike, toLike ControlLike, pointLike PointLike) *Point {
	var from *Control
	if fromLike != nil {
		from = fromLike.AsControl()
	}
	_ = from
	var to *Control
	if toLike != nil {
		to = toLike.AsControl()
	}
	_ = to
	var point *Point
	if pointLike != nil {
		point = pointLike.AsPoint()
	}
	_ = point
	this.impl.checkDevice_()
	if point == (nil) {
		this.Error(ERROR_NULL_ARGUMENT)
	}
	return this.MapFromToXY(from, to, point.X, point.Y)
}

func (this *Display) MapFromToRectangle(fromLike ControlLike, toLike ControlLike, rectangleLike RectangleLike) *Rectangle {
	var from *Control
	if fromLike != nil {
		from = fromLike.AsControl()
	}
	_ = from
	var to *Control
	if toLike != nil {
		to = toLike.AsControl()
	}
	_ = to
	var rectangle *Rectangle
	if rectangleLike != nil {
		rectangle = rectangleLike.AsRectangle()
	}
	_ = rectangle
	this.impl.checkDevice_()
	if rectangle == (nil) {
		this.Error(ERROR_NULL_ARGUMENT)
	}
	return this.MapFromToXYWidthHeight(from, to, rectangle.X, rectangle.Y, rectangle.Width, rectangle.Height)
}

func (this *Display) MapFromToXY(fromLike ControlLike, toLike ControlLike, x int32, y int32) *Point {
	var from *Control
	if fromLike != nil {
		from = fromLike.AsControl()
	}
	_ = from
	var to *Control
	if toLike != nil {
		to = toLike.AsControl()
	}
	_ = to
	this.impl.checkDevice_()
	if from != (nil) && from.IsDisposed() {
		this.Error(ERROR_INVALID_ARGUMENT)
	}
	if to != (nil) && to.IsDisposed() {
		this.Error(ERROR_INVALID_ARGUMENT)
	}
	var point *Point = NewPoint(x, y)
	if from == to {
		return point
	}
	if from != (nil) {
		var origin *Point
		if gtk.GTKGTK4 {
			origin = from.impl.getSurfaceOrigin_()
		} else {
			origin = from.impl.getWindowOrigin_()
		}
		if (from.style & MIRRORED) != 0 {
			point.X = from.impl.getClientWidth_() - point.X
		}
		point.X += origin.X
		point.Y += origin.Y
	}
	if to != (nil) {
		var origin *Point
		if gtk.GTKGTK4 {
			origin = to.impl.getSurfaceOrigin_()
		} else {
			origin = to.impl.getWindowOrigin_()
		}
		point.X -= origin.X
		point.Y -= origin.Y
		if (to.style & MIRRORED) != 0 {
			point.X = to.impl.getClientWidth_() - point.X
		}
	}
	return point
}

func (this *Display) MapFromToXYWidthHeight(fromLike ControlLike, toLike ControlLike, x int32, y int32, width int32, height int32) *Rectangle {
	var from *Control
	if fromLike != nil {
		from = fromLike.AsControl()
	}
	_ = from
	var to *Control
	if toLike != nil {
		to = toLike.AsControl()
	}
	_ = to
	this.impl.checkDevice_()
	if from != (nil) && from.IsDisposed() {
		this.Error(ERROR_INVALID_ARGUMENT)
	}
	if to != (nil) && to.IsDisposed() {
		this.Error(ERROR_INVALID_ARGUMENT)
	}
	var rect *Rectangle = NewRectangle(x, y, width, height)
	if from == to {
		return rect
	}
	var fromRTL bool = false
	var toRTL bool = false
	if from != (nil) {
		var origin *Point
		if gtk.GTKGTK4 {
			origin = from.impl.getSurfaceOrigin_()
		} else {
			origin = from.impl.getWindowOrigin_()
		}
		cond282 := (from.style & MIRRORED) != 0
		fromRTL = cond282
		if cond282 {
			rect.X = from.impl.getClientWidth_() - rect.X
		}
		rect.X += origin.X
		rect.Y += origin.Y
	}
	if to != (nil) {
		var origin *Point
		if gtk.GTKGTK4 {
			origin = to.impl.getSurfaceOrigin_()
		} else {
			origin = to.impl.getWindowOrigin_()
		}
		rect.X -= origin.X
		rect.Y -= origin.Y
		cond283 := (to.style & MIRRORED) != 0
		toRTL = cond283
		if cond283 {
			rect.X = to.impl.getClientWidth_() - rect.X
		}
	}
	if fromRTL != toRTL {
		rect.X -= rect.Width
	}
	return rect
}

