// j2go: instanceof helper for Menu and its subclasses within the translated set.
func widgetImplAsMenu(x any) (*Menu, bool) {
	if h, ok := x.(*widgetHooked); ok {
		x = h.hook
	}
	switch v := x.(type) {
	case *Menu:
		if v == nil {
			return nil, false
		}
		return v, true
	}
	if l, ok := x.(interface{ AsMenu() *Menu }); ok {
		return l.AsMenu(), true
	}
	return nil, false
}

func isWidgetToMenu(x *Widget) (*Menu, bool) {
	if x == nil {
		return nil, false
	}
	return widgetImplAsMenu(x.impl)
}

